-- ------------------------------------------------------------
-- IMPLEMENTATION REQUIRED: No overlapping approved bookings
-- BR: BR-9 (also tied to BR-8 approved status)
-- Tables: BOOKING_REQUEST
-- Enforce: Same space cannot have two approved bookings with overlapping requested time periods.
-- ------------------------------------------------------------
CREATE TRIGGER dbo.TR_BOOKING_REQUEST_NoOverlap ON dbo.BOOKING_REQUEST
AFTER INSERT, UPDATE
AS
BEGIN
    SET NOCOUNT ON;

    IF EXISTS (
        SELECT 1
        FROM inserted i
        JOIN dbo.BOOKING_REQUEST b
          ON b.space_id = i.space_id
         AND b.booking_id <> i.booking_id
         AND b.status = N'Approved'
         AND i.status = N'Approved'
         AND i.requested_start_time < b.requested_end_time
         AND i.requested_end_time > b.requested_start_time
    )
    BEGIN
        RAISERROR(N'Approved booking overlaps an existing approved booking for the same space.', 16, 1);
        ROLLBACK TRANSACTION;
        RETURN;
    END;
END;
GO

-- ------------------------------------------------------------
-- IMPLEMENTATION REQUIRED: Unavailable-space booking prevention
-- BR: BR-10, BR-19
-- Tables: BOOKING_REQUEST, SPACE
-- Enforce: Prevent booking rows for spaces whose current_status is Under maintenance,
--          Temporarily closed, or Retired.
-- ------------------------------------------------------------
CREATE TRIGGER dbo.TR_BOOKING_REQUEST_SpaceAvailability ON dbo.BOOKING_REQUEST
AFTER INSERT, UPDATE
AS
BEGIN
    SET NOCOUNT ON;

    IF EXISTS (
        SELECT 1
        FROM inserted i
        JOIN dbo.SPACE s ON s.space_id = i.space_id
        WHERE s.current_status IN (N'Under maintenance', N'Temporarily closed', N'Retired')
    )
    BEGIN
        RAISERROR(N'Space is under maintenance, temporarily closed, or retired and cannot be booked.', 16, 1);
        ROLLBACK TRANSACTION;
        RETURN;
    END;
END;
GO

