-- TABLE: APPROVAL_DECISION
-- Source: Logical Design §2.6
-- ============================================================
CREATE TABLE dbo.APPROVAL_DECISION (
    approval_decision_id INT IDENTITY(1,1) NOT NULL,
    booking_id INT NOT NULL,
    decision_maker_user_account_id INT NOT NULL,
    decision_outcome NVARCHAR(20) NOT NULL,
    decision_time DATETIME2(0) NOT NULL,
    decision_note NVARCHAR(1000) NULL,
    rejection_reason NVARCHAR(1000) NULL,
    CONSTRAINT PK_APPROVAL_DECISION PRIMARY KEY (approval_decision_id),
    CONSTRAINT FK_APPROVAL_DECISION_booking_id FOREIGN KEY (booking_id) REFERENCES dbo.BOOKING_REQUEST(booking_id) ON DELETE NO ACTION ON UPDATE NO ACTION,
    CONSTRAINT FK_APPROVAL_DECISION_decision_maker_user_account_id FOREIGN KEY (decision_maker_user_account_id) REFERENCES dbo.USER_ACCOUNT(user_account_id) ON DELETE NO ACTION ON UPDATE NO ACTION,
    CONSTRAINT CK_APPROVAL_DECISION_decision_outcome CHECK (decision_outcome IN (N'Approved', N'Rejected')),
    CONSTRAINT CK_APPROVAL_DECISION_rejection_reason CHECK (decision_outcome <> N'Rejected' OR rejection_reason IS NOT NULL)
);
GO

