-- ------------------------------------------------------------
-- IMPLEMENTATION REQUIRED: Approval decision maker role restriction
-- BR: BR-11, BR-12
-- Tables: APPROVAL_DECISION, USER_ACCOUNT
-- Enforce: Decision maker must have role Facility Staff or Facility Manager.
-- ------------------------------------------------------------
CREATE TRIGGER dbo.TR_APPROVAL_DECISION_RoleCheck ON dbo.APPROVAL_DECISION
AFTER INSERT, UPDATE
AS
BEGIN
    SET NOCOUNT ON;

    IF EXISTS (
        SELECT 1
        FROM inserted i
        JOIN dbo.USER_ACCOUNT u ON u.user_account_id = i.decision_maker_user_account_id
        WHERE u.role NOT IN (N'Facility Staff', N'Facility Manager')
    )
    BEGIN
        RAISERROR(N'Approval decision maker must be Facility Staff or Facility Manager.', 16, 1);
        ROLLBACK TRANSACTION;
        RETURN;
    END;
END;
GO

-- ------------------------------------------------------------
-- IMPLEMENTATION REQUIRED: Rejected decision rejection reason
-- BR: BR-13
-- Tables: APPROVAL_DECISION
-- Enforce: When decision_outcome = Rejected, rejection_reason must be non-null.
-- Note: This rule is already enforced by CK_APPROVAL_DECISION_rejection_reason.
--       Trigger shell retained to satisfy implementation-stub traceability.
-- ------------------------------------------------------------
CREATE TRIGGER dbo.TR_APPROVAL_DECISION_RejectionReason ON dbo.APPROVAL_DECISION
AFTER INSERT, UPDATE
AS
BEGIN
    SET NOCOUNT ON;

    IF EXISTS (
        SELECT 1
        FROM inserted i
        WHERE i.decision_outcome = N'Rejected'
          AND i.rejection_reason IS NULL
    )
    BEGIN
        RAISERROR(N'Rejected approval decisions require a rejection reason.', 16, 1);
        ROLLBACK TRANSACTION;
        RETURN;
    END;
END;
GO

