-- ------------------------------------------------------------
-- IMPLEMENTATION REQUIRED: Completion consistency
-- BR: BR-16
-- Tables: USAGE_SESSION
-- Enforce: Completion fields actual_end_time, completed_by_user_account_id, and
--          final_condition_of_space must be all null or all non-null.
-- Note: This rule is already enforced by CK_USAGE_SESSION_completion_fields.
--       Trigger shell retained to satisfy implementation-stub traceability.
-- ------------------------------------------------------------
CREATE TRIGGER dbo.TR_USAGE_SESSION_CompletionConsistency ON dbo.USAGE_SESSION
AFTER INSERT, UPDATE
AS
BEGIN
    SET NOCOUNT ON;

    IF EXISTS (
        SELECT 1
        FROM inserted i
        WHERE NOT (
            (i.actual_end_time IS NULL AND i.completed_by_user_account_id IS NULL AND i.final_condition_of_space IS NULL)
            OR
            (i.actual_end_time IS NOT NULL AND i.completed_by_user_account_id IS NOT NULL AND i.final_condition_of_space IS NOT NULL)
        )
    )
    BEGIN
        RAISERROR(N'Usage-session completion fields must be all null or all non-null.', 16, 1);
        ROLLBACK TRANSACTION;
        RETURN;
    END;
END;
GO

